,
[4112] = {
["description"] = "Vainquez toutes les rencontres en plus du bourreau Jerensi, du sorcier primat Vandorallen et du Grain punitif en moins de 25 minutes après être entrés dans la redoute de l\'Exil. Votre chronomètre commence lorsque vous attaquez le premier ennemi.",
["name"] = "La prompte main de la justice",
}
,
[4113] = {
["description"] = "Venez à bout de toutes les rencontres en plus du bourreau Jerensi, du sorcier primat Vandorallen et du Grain punitif dans la redoute de l\'Exil Vétéran sans qu\'un seul membre du groupe ne meure.",
["name"] = "Sans une ombre",
}
,
[4114] = {
["description"] = "Accomplissez les succès listés dans la redoute de l\'Exil.",
["name"] = "Concurrent de la redoute de l\'Exil",
}
,
[4115] = {
["description"] = "Vainquez toutes les rencontres en plus du bourreau Jerensi, du sorcier primat Vandorallen et du Grain punitif après avoir placé les étendards de défi dans la redoute de l\'Exil en moins de 25 minutes sans qu\'un seul membre du groupe ne meure. Votre chronomètre commence lorsque vous attaquez le premier groupe d\'ennemis.",
["name"] = "Vengeance brisée",
}
,
[4116] = {
["description"] = "En mode Vétéran, affrontez la bourreau Jerensi sans vous faire toucher par ses pièges à épieux dans la redoute de l\'Exil Vétéran.",
["name"] = "Exécution évitée",
}
,
[4117] = {
["description"] = "Pendant le combat contre le Grain punitif, prenez un orbe de feu, de glace ou de foudre avant qu\'il ne se développe en Éruption embrasée, Éruption glacée ou Explosion de foudre et vainquez le Grain punitif dans la redoute de l\'Exil.",
["name"] = "Défragmenté",
}
,
[4120] = {
["description"] = "Dans un groupe de 4 joueurs, après avoir dressé l\'étendard de défi, vainquez le Grain punitif seulement après que chaque membre de votre groupe a ramassé un orbé élémentaire de chaque couleur dans la redoute de l\'Exil Vétéran.",
["name"] = "Exposition aux éléments",
}
,
[4121] = {
["description"] = "Au cours de la même expédition dans la redoute de l\'Exil, vainquez le capitaine de la garde Paratius, le professeur Domitius et Éliana Albus avant de vaincre le Grain punitif.",
["name"] = "Repos retrouvé",
}
,
[4122] = {
["description"] = "Vainquez le bourreau Jerensi après avoir dressé l\'étendard de défi dans la redoute de l\'Exil Vétéran.",
