}
,
[1518] = {
["description"] = "Vainquez la Sylvegarde Na-Kesh dans les ruines de Mazzatun Vétéran sans qu\'un seul membre du groupe utilise la synergie Révélation pour identifier le véritable avatar de l\'Hist.",
