,
[2232] = {
["description"] = "En affrontant Z\'Maja avec les trois ombres des welkynars avec eux, un joueur avec l\'affliction Givrée et deux autres joueurs avec l\'affliction Surcharge voltaïque partagent les dégâts de l\'éruption de Feu rugissant dans le Pas-des-Nuées Vétéran.",
