,
[2370] = {
["description"] = "Vainquez Dompte-la-Bête sans qu\'un membre du groupe ne soit piégé par les Racines écrasantes dans la Prison de la Rose noire Vétéran.",
["name"] = "Rarement enraciné",
}
,
[2371] = {
["description"] = "Vainquez dame Minara après que trois colosses d\'os auront été invoqués dans les 30 premières secondes du combat, dans la Prison de la Rose noire Vétéran.",
["name"] = "Invocation de squelettes",
}
,
[2372] = {
["description"] = "Vainquez la mage de bataille Ennodius, dame Minnara et Dompte-la-Bête à 20 secondes d\'intervalle dans la Prison de la Rose noire Vétéran.",
["name"] = "Triplette terrifiante",
}
,
[2373] = {
["description"] = "Vainquez Drakeeh le Déchaîné tout en vous assurant qu\'il absorbe toujours au moins 2 esprits avant de lancer Cri spirituel dans la Prison de la Rose noire.",
["name"] = "Esprits scindés",
}
,
[2374] = {
["description"] = "Utilisez la compétence Météore de la mage de bataille Ennodius pour sonner les quatre atronachs simultanément dans la première arène de la Prison de la Rose noire.",
["name"] = "Manège des météores",
}
,
[2375] = {
["description"] = "Utilisez un Sceau de résurrection dans n\'importe quelle arène pour ranimer trois autres membres du groupe en même temps dans la Prison de la Rose noire.",
