}
,
[2380] = {
["description"] = "Poussez Traqueglace à frapper ses alliés pendant le Martèlement frénétique dans Arquegivre.",
["name"] = "Frappes aveugles",
}
,
[2381] = {
["description"] = "Esquivez systématiquement les charges imprudentes du seigneur de guerre Tzogvin dans Arquegivre.",
["name"] = "Trouver le bon angle",
}
,
[2382] = {
["description"] = "Poussez le seigneur de guerre Tzogvin à détruire ses trois étendards avec des Cyclônes dans Arquegivre.",
["name"] = "Toutes voiles dehors",
}
,
[2384] = {
["description"] = "Vainquez Rizzuk et Avalanche dans Arquegivre après que chaque membre du groupe a été affecté par la Prison glaciale d\'Avalanche au moins une fois pendant le combat dans Arquegivre Vétéran.",
["name"] = "Patate froide",
}
,
[2385] = {
["description"] = "Faites tomber 20 ennemis de la plateforme du Gardien de pierre dans Arquegivre.",
["name"] = "La gravité de la chute",
}
,
[2386] = {
["description"] = "Prenez le contrôle de chaque type de ragnaton modifié. Les ragnatons modifiés sont disponibles pendant la phase Protocole d\'extermination du combat contre le Gardien des pierres, après avoir activé le Vérificateur de véracité dans Arquegivre Vétéran. Vous ne pouvez pas être mort ou Ferraille à la fin du combat si vous voulez recevoir le crédit.",
["name"] = "Une variété de vermines",
}
,
[2387] = {
["description"] = "Désactivez le Protocole d\'extermination du Gardien des pierres avec les ragnatons de Tharayya en moins de 35 secondes après leur invocation dans Arquegivre. Le chronomètre commence au début de sa mise en garde.",
["name"] = "Course au fromage",
}
,
[2388] = {
["description"] = "Aucun proboscis en maraude de la Gueule charognarde ne doit être brisé, et aucune de ses formes d\'ombre ne doit vous toucher dans les Profondeurs de Malatar Vétéran.",
["name"] = "Cache-cache",
}
,
[2389] = {
["description"] = "Aucun membre du groupe ne doit être frappé par Glaciation pendant votre combat contre la Pleureuse dans les Profondeurs de Malatar Vétéran.",
["name"] = "Glissade",
}
,
[2390] = {
["description"] = "Ne détruisez aucun orbe coloré pendant la rencontre de l\'Orbe noir dans les Profondeurs de Malatar.",
["name"] = "Daltonisme",
}
,
[2391] = {
["description"] = "Empêchez Quintus de remporter son duel avec Tharayya pendant le combat contre le roi Narilmor dans les Profondeurs de Malatar.",
["name"] = "Âmes sœurs",
}
,
[2392] = {
["description"] = "Vainquez chaque couleur d\'Aurorien pendant la bataille contre la Symphonie de lames dans les Profondeurs de Malatar.",
["name"] = "Moisson d\'arc-en-ciel",
}
,
[2393] = {
["description"] = "Empêchez la Symphonie de lames de traverser la Phalange aurorienne et d\'être renforcée par la lumière de Méridia dans les Profondeurs de Malatar Vétéran.",
["name"] = "Hors de la formation",
}
,
[2395] = {
["description"] = "Après avoir lu le Dictat de la Dame de la Lumière, entrez dans la salle colorée sans laisser un seul orbe coloré en vie pendant la rencontre avec la Symphonie des Lames dans les Profondeurs de Malatar Vétéran.",
